div.t-attf-style:
background-color: {{ 'rgba(40, 167, 69, 0.08)' if license_status == 'valid' else 'rgba(245, 124, 0, 0.08)' if license_status == 'warning' else 'rgba(211, 47, 47, 0.08)' }}; 
                                       border-color: {{ 'rgba(40, 167, 69, 0.18)' if license_status == 'valid' else 'rgba(245, 124, 0, 0.18)' if license_status == 'warning' else 'rgba(211, 47, 47, 0.18)' }}; 
                                       color: {{ '#1b5e20' if license_status == 'valid' else '#e65100' if license_status == 'warning' else '#b71c1c' }}; 
                                       font-size: 0.8rem; font-weight: 500; font-family: sans-serif;
